// Cadre du dessin, celui du site : viewBox="26 -720 4461 936".
private const val CADRE_X = 26f
private const val CADRE_Y = -720f
private const val CADRE_LARGEUR = 4461f
private const val CADRE_HAUTEUR = 936f

/**
 * Le mot « Canapilou » en deux couleurs, [hauteur] de haut (largeur selon ses
 * proportions, environ 4,8 fois la hauteur). Lu « Canapilou » par les lecteurs
 * d'écran. Taille fixe, comme un logo : elle ne suit pas la taille du texte
 * choisie dans les réglages du téléphone.
 */
@Composable
fun MotCanapilou(hauteur: Dp, modifier: Modifier = Modifier) {
    val couleurCanap = MaterialTheme.colorScheme.secondary
    val couleurIlou = MaterialTheme.colorScheme.primary
    // Dessin refait seulement quand les couleurs changent (thème clair ou sombre).
    val dessin = remember(couleurCanap, couleurIlou) {
        ImageVector.Builder(
            name = "Canapilou",
            defaultWidth = (100 * CADRE_LARGEUR / CADRE_HAUTEUR).dp,
            defaultHeight = 100.dp,
            viewportWidth = CADRE_LARGEUR,
            viewportHeight = CADRE_HAUTEUR,
        )
            // Le cadre du site commence en (26, -720) : on décale le dessin pour
            // qu'il commence en (0, 0), comme le veut Android.
            .addGroup(translationX = -CADRE_X, translationY = -CADRE_Y)
            .addPath(addPathNodes(TRACE_CANAP), fill = SolidColor(couleurCanap))
            .addPath(addPathNodes(TRACE_ILOU), fill = SolidColor(couleurIlou))
            .clearGroup()
            .build()
    }
    Image(
        imageVector = dessin,
        contentDescription = "Canapilou",
        modifier = modifier
            .height(hauteur)
            .aspectRatio(CADRE_LARGEUR / CADRE_HAUTEUR),
    )
}
